/*(I appologize for my english, I haven't being practicing lately)

 The particle system is the sparks of the shootingstar. 

 It is kinda hard to notice with the shooting star moving so quikly, but
if you chage speed_A(line 113) and speed_B(line 114) to smaller numbers(ex: 2 and 1) you 
will be able to notice that the sparks are a bunch of particles moving around.

  Requirementes of the homework:
	 - position;(line 51,52,59,60,67,68,75,76,86 and 111)
	 - size;(line 53,61,69,77 and 88)
	 - color;(line 54,62,70,78 and 89)
	 - speed.(line 87, 113 and 114)

  To interact with the sketch:
   - Move your mouse to see the stars change;
	 - Click with your mouse to "release" a shotting star.

  In this sketch I tried to use the things we learned this week to make a shootingstar,
 the idea was to make an emitter move across the canvas so it would look like a 
 shootingstar.
  The Shottingstar(line 109) is the emitter and the Sparks(line 82)are the particles

  I also tried being more creative with this one, that's why I included the moon and 
 the city skyline.
  The moon is basically 4 ellipses of diferent sizes and alphas. The ellipses are organized 
	in a bigger to smaller order.
  The skyline is 2 triangles and 27 rectangles. Since it has so many shapes I tried 
	putting the triangles first then the rectangles in a "right to left" order.

  It was also my first time using "class" and "arrays", so I tried doing something else 
 with them.That's why I made the stars. I wanted to put them all in one class and try 
 to use only one array, but I couldn't make it work.

  By the way, I'm new to coding so I'd apreciate some tips.

  I hope you like it! :)
*/

//Arrays
var stars = [];
var stars_2 = [];
var stars_3 = [];
var stars_4 = [];
var shootingStars = [];
var sparks = [];


class Star {
	constructor(posX, posY){
			this.positionX = posX;//Star position on the X axis
			this.positionY = posY;//Star position on the Y axis
	    this.size = 2;//Star size
			this.col = color(255);//Star color
	}
}
class Star_2 {
	constructor(posX, posY){
			this.positionX = posX;//Star_2 position on the X axis
			this.positionY = posY;//Star_2 position on the Y axis
		  this.size = 2.5;//Star_2 size
			this.col = color(255);//Star_2 color
	}
}
class Star_3 {
	constructor(posX, posY){
			this.positionX = posX;//Star_3 position on the X axis
			this.positionY = posY;//Star_3 position on the Y axis
		  this.size = 4;//Star_3 size
			this.col = color(255);//Star_3 color
	}
}
class Star_4 {
	constructor(posX, posY){
			this.positionX = posX;//Star_4 position on the X axis
			this.positionY = posY;//Star_4 position on the Y axis
		  this.size = 6;//Star_4 size
			this.col = color(255);//Star_4 color
	}
}

class Sparks {
  constructor(x, y) {
		var colorFrom = color(255,64,0);//Reddish Orange
		var colorTo = color(255,191,0);//Yellow
    this.pos = createVector(x, y);//Creates a new p5.Vector/Sparks position
    this.speed = createVector(random(2));//Creates a new p5.Vector/Sparks speed
    this.size = 5;//Sparks size
		this.color = lerpColor(colorFrom,colorTo,random(1));//Sparks color
    this.lifespan = 255;//Sparks lifespan
	}
  update() {
	 //Adds speed to the position vector
    this.pos.add(this.speed);

	 //Subtract assign 20 / now lifespan = 235
    this.lifespan -= 20;
	}
	//"Shows" the sparks shape and color
  show() {
	 //Removes stroke
		noStroke();
	 //Color of the sparks
    fill(this.color,this.lifespan);
	 //Shape of the sparks
    ellipse(this.pos.x,this.pos.y,this.size,this.size);
	}
}
class ShootingStars {
  constructor() {
		this.pos = createVector(0,0);//Creates a new p5.Vector/ShootingStars position
    this.sparks = [];//sparks array
    this.speed_A  = 15;//ShootingStars X axis speed
    this.speed_B  = 6;//ShootingStars Y axis speed
    this.lifespan = 255;//ShootingStars lifespan
	  }
	//Moves the shootingstar
  move(){
		//If the ShootingStars position is smaller than width...
    if (this.pos.x < width){
			//Multiplies speed_A by 1
        this.speed_A *= 1;
    }
		//If the ShootingStars position is smaller than height..
    if (this.pos.y < height){
			//Multiplies speed_B by 1
         this.speed_B *= 1;
    }
		//Adds a new class to position vector
    this.pos.add(new p5.Vector(this.speed_A,this.speed_B));
		//If the lifespan in higher then 0...
    if(this.lifespan > 0){
			//Subtract 1 (-- is the same as -=1)
       this.lifespan --;
    }
	}
	//Emits sparks/particles
  emit(numParticles) {
    for (var i = 0; i < numParticles; i++) {
		 //Adds Sparks to the sparks array
      this.sparks.push(new Sparks(this.pos.x,this.pos.y));
		}
	  for (var j=0; j < this.sparks.length; j++) {
			//Assigns the sparks array to a variable
	        var spark = this.sparks[j];
			  //If the lifespan in equal or bellow 0..
          if(spark.lifespan <= 0){
						//Remove 1 ellement
	            sparks.splice(j,1);
				//If the lifespan in higher then 0...
			    }else{
           spark.update();
	         spark.show();//Shows the sparks shapes
          }
		}
	}
}



function setup() {
  createCanvas(700,500);//Sets canvas size

	//Adds ShootingStars to the shootingStars array
   shootingStars.push(new ShootingStars(width/2,height/2));

	//Stars' loops
	 for(var i=0; i<300; i++){
		 //Adds Star to the stars array
	   stars.push(new Star(random(width),random(height)));
	 }
	 for(var j=0; j<250; j++){
		 //Adds Star_2 to the stars_2 array
	   stars_2.push(new Star_2(random(width),random(height)));
	 }
	 for(var k=0; k<200; k++){
		 //Adds Star_3 to the stars_3 array
	   stars_3.push(new Star_3(random(width),random(height)));
	 }
	 for(var l=0; l<150; l++){
		 //Adds Star_4 to the stars_4 array
	   stars_4.push(new Star_4(random(width),random(height)));
	 }
}

function draw() {
  background(0,0,51);//Sets background color / blue

	for(var i=0; i < stars.length; i++){
		//Assigns the stars array to a variable
		var star = stars[i];
		//lerpAmt changes depending on the mouse Y position
		 lerpAmt = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),0,width,0,1);
		//Stars Color variable/it goes from blue(sky/background color) to white(star.col) 
		 var starColor = lerpColor(color(0,0,51),color(star.col),lerpAmt);
		//Color of the stars
		 fill(starColor);
		//Removes the stroke
     noStroke();
		//Stars shape
	   ellipse(star.positionX, star.positionY, star.size,star.size); 
	}

	for(var j=0; j < stars_2.length; j++){
	 //Assigns the stars_2 array to a variable
		var star_2 = stars_2[j];
		//lerpAmt changes depending on the mouse Y position
		 lerpAmt = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),0,width,0,1);
		//Stars Color variable/it goes from white(star_2.col) to blue(sky/background color)
		 var starColor_2 = lerpColor(color(star_2.col),color(0,0,51),lerpAmt);
		//Color of the stars
		 fill(starColor_2);
		//Removes the stroke
     noStroke();
		//Stars shape
	  ellipse(star_2.positionX, star_2.positionY, star_2.size,star_2.size); 
	}

	for(var k=0; k < stars_3.length; k++){
	 //Assigns the stars_3 array to a variable
	 var star_3 = stars_3[k];
		//lerpAmt changes depending on the mouse X position
		 lerpAmt = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),0,width,0,1);
		//Stars Color variable/it goes from blue(sky/background color) to white(star_3.col)  
		 var starColor_3 = lerpColor(color(0,0,51),color(star_3.col),lerpAmt);
		//Color of the stars
		 fill(starColor_3);
		//Removes the stroke
     noStroke();
		//Stars shape
	   ellipse(star_3.positionX, star_3.positionY,star_3.size,star_3.size); 
	}

	for(var l=0; l < stars_4.length; l++){
	 //Assigns the stars_4 array to a variable
	 var star_4 = stars_4[l];
		//lerpAmt changes depending on the mouse X position
		 lerpAmt = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),0,width,0,1);
		//Stars Color variable/it goes from white(star_4.col) to blue(sky/background color)
		 var starColor_4 = lerpColor(color(star_4.col),color(0,0,51),lerpAmt);
		//Color of the stars
		 fill(starColor_4);
		//Removes the stroke
     noStroke();
		//Stars shape
	   ellipse(star_4.positionX, star_4.positionY,star_4.size,star_4.size); 
	}

  for(var m=0; m < shootingStars.length; m++){
		//Assigns the shootingStars array to a variable
    var shootingStar = shootingStars[m];
		 //If the lifespan in equal or bellow 0..
       if(shootingStar.lifespan <= 0){
				//Remove 1 ellement
	       shootingStars.splice(m,1);
		 //If the lifespan in higher then 0...
        } else { 
        shootingStar.move();//moves the shootingstar
        shootingStar.emit(4);//emit sparks
       }
  }      

	push();
	 Moon(620,70);//Calls Moon function (line 273)
	pop();

	push();
	 CitySkyline();//Calls CitySkyline function (line 286)
	pop();
}

// MOON //
function Moon(posX,posY){
noStroke();//Removes the stroke
fill(255,10);
ellipse(posX,posY,160,160);
fill(255,15);
ellipse(posX,posY,120,120);
fill(255,25);
ellipse(posX,posY,100,100);
fill(255);
ellipse(posX,posY,80,80);
}

// CITY SKYLINE //
function CitySkyline(){
 //Removes the stroke
  noStroke();
 //shapes color / Black
  fill(0);
 //Shapes
  triangle(40,360,80,400,40,400);//Right_triangle
  triangle(380,450,460,340,460,450);//Left_triangle
  rect(0,260,10,60);
  rect(0,320,40,180);
  rect(10,305,20,15);
  rect(40,400,90,100);
	rect(110,377.5,20,30);
	rect(130,340,90,160);
  rect(150,300,10,40);
	rect(180,325,25,15);
  rect(190,240,5,85);
  rect(220,400,40,100);
  rect(260,380,40,120);
	rect(265,375,30,5);
  rect(300,300,40,200);
  rect(305,295,30,5);
	rect(340,345,40,155);
  rect(345,340,30,5);
  rect(380,450,80,50);
  rect(460,250,80,250);
	rect(480,225,10,25);
  rect(500,205,5,45);
  rect(540,290,50,210);
  rect(550,285,30,5);
  rect(590,320,110,180);
  rect(625,320,10,60);
  rect(635,310,40,10);
  rect(660,300,5,10);
  rect(680,220,20,100);
}

//When the mouse is pressed it "releases" a shootingstar
function mousePressed(){
 //Adds ShootingStars to the shootingStars array
  shootingStars.push(new ShootingStars(createVector(width/2, height/2)));
}

/*
=> .push() 
    Adds an element to the end of an array

=> .length 
   Tells how many ellements are in the array

=> .splice() 
    Removes especiffic elements from an array

=> .add() 
   "Adds x, y and z components to a vector, adds one vector to another,
    or adds two independent vectors together."

=> new p5.Vector() 
   "A class to describe a two or three dimensional vector."

=> createVector()
   "Creates a new p5.Vector(the datatype for storing vectors)."

=> map();
  "Re-maps a number from one range to another."
	- (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) minimun is 0 and maximun is width.
	- (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) minimun is 0 and maximun is height
	- lerpAmt minimun is 0 and maximun is 1.

=> translate(); :
   moves the drawing origin by X  and Y values.

=> push(); Start a new drawing state
=> pop(); Restores original/previous state

=> ellipse(positionX,positionY,width,height);
=> rect(positionX,positionY,width,height);

=> for loop:
   for(start condition; exit condition; iterator){
	    expressions happen each loop
	   };

=> lerpColor(colorFrom, colorTo,lerpAmnt);
  -colorFrom: First color of the gradient
	-colorTo: Last color of the gradient
	-lerpAmnt:
   is the amount to interpolate between the two values where 0.0 equal to the first 
	 color(colorFrom), and 1.0 equal to the last color (colorTo)
*/

